<template>
  <div class="container">
    <h1>Tabla de Clientes</h1>
    <table>
      <thead>
        <tr>
          <th>Cédula</th>
          <th>Nombre</th>
          <th>Correo electrónico</th>
          <th>Teléfono</th>
        </tr>
      </thead>
      <tbody>
        <tr v-for="cliente in clientes" :key="cliente.cedula">
          <td>{{ cliente.cedula }}</td>
          <td>{{ cliente.nombre }}</td>
          <td>{{ cliente.correo }}</td>
          <td>{{ cliente.telefono }}</td>
        </tr>
      </tbody>
    </table>
  </div>
</template>


<script>
import axios from "axios";

export default {
  data(){
    return {
      // 1. Lo cambiamos a plural para que coincida con tu v-for="cliente in clientes"
      clientes: [], 
    };
  },
  methods:{
    obtenerClientes(){
      // 2. Le agregamos el /api/ a la ruta para que Spring Boot la reconozca
      axios.get('http://localhost:8080/api/cliente/listar')
        .then(response => {
            // 3. Guardamos los datos en la variable en plural
            this.clientes = response.data;
        })
        .catch(error => {
            console.error("Error al obtener la lista de clientes:", error);
        });
    }
  },
  mounted(){
    this.obtenerClientes();
  },
};
</script>


    


