<template>
  <div class="container">
    <h1>Formulario de Cliente</h1>
    
    <form id="client-form" @submit.prevent="submitForm">
      <div class="form-group">
        <label for="cedula">Cedula:</label>
        <input type="text" id="cedula" v-model="cliente.cedula" required />
      </div>
      
      <div class="form-group">
        <label for="name">Nombre:</label>
        <input type="text" id="name" v-model="cliente.name" required />
      </div>
      
      <div class="form-group">
        <label for="email">Correo electrónico:</label>
        <input type="email" id="email" v-model="cliente.email" required />
      </div>
      
      <div class="form-group">
        <label for="phone">Telefono:</label>
        <input type="tel" id="phone" v-model="cliente.phone" required />
      </div>

      <button type="submit">Guardar</button>
      <button type="button" @click="eliminarCliente">Eliminar / Limpiar</button>
      <button type="button" @click="actualizarCliente">Actualizar</button>
      <button type="button" @click="consultarCliente">Consultar</button>

    </form>
  </div> 
</template>

<script>
import axios from 'axios';

export default {
  name: "FormularioCliente",
  data() {
    return {
      cliente: {
        id: null, // ¡No borres esto! Es necesario para actualizar y eliminar
        cedula: "",
        name: "",
        email: "",
        phone: ""
      }
    };
  },
  methods: {
    async submitForm() {
      try {
        const respuesta = await axios.post('http://localhost:8080/api/cliente', {
          cedula: this.cliente.cedula,
          nombre: this.cliente.name,
          correo: this.cliente.email,
          telefono: this.cliente.phone
        }); // 
        
        this.$emit("actualizarTabla"); 

        console.log("Respuesta del servidor:", respuesta.data);
        alert(`¡Éxito! El cliente ${this.cliente.name} se guardó en la base de datos.`);
        
        this.resetForm();

      } catch (error) {
        console.error("Hubo un error al guardar:", error);
        alert("No se pudo guardar el cliente. Verifica que tu Spring Boot esté encendido.");
      }
    },

    consultarCliente() {
      axios.get("http://localhost:8080/api/cliente/" + this.cliente.cedula)
        .then(response => {
          const clienteData = response.data;
          
          this.cliente.id = clienteData.id_clientes; 
          this.cliente.name = clienteData.nombre;
          this.cliente.email = clienteData.correo;
          this.cliente.phone = clienteData.telefono;
          
          alert("Cliente encontrado y cargado en el formulario.");
        })
        .catch(error => {
          console.error("Error al consultar el cliente:", error);
          alert("No se pudo encontrar un cliente con esa cédula.");
        });
    },

    async actualizarCliente() {
      if (!this.cliente.id) {
        alert("Primero debes consultar un cliente con su cédula para poder actualizarlo.");
        return;
      }

      try {
        await axios.put("http://localhost:8080/api/cliente/actualizar/" + this.cliente.id, {
          cedula: this.cliente.cedula,
          nombre: this.cliente.name,
          correo: this.cliente.email,
          telefono: this.cliente.phone
        });
        
        // También puedes emitir el evento aquí para que la tabla se actualice al editar
        this.$emit("actualizarTabla");
        alert(`¡Los datos de ${this.cliente.name} fueron actualizados correctamente!`);
        
      } catch (error) {
        console.error("Hubo un error al actualizar:", error);
        alert("No se pudo actualizar el cliente. Revisa la consola.");
      }
    },

    async eliminarCliente() {
      if (!this.cliente.id) {
        alert("Primero debes consultar un cliente con su cédula para poder eliminarlo.");
        return;
      }

      const confirmacion = confirm(`¿Estás seguro de que quieres eliminar a ${this.cliente.name} por completo?`);
      
      if (confirmacion) {
        try {
          await axios.delete('http://localhost:8080/api/cliente/' + this.cliente.id);
          
          
          this.$emit("actualizarTabla");
          alert("¡Cliente eliminado de la base de datos!");
          this.resetForm(); 
          
        } catch (error) {
          console.error("Error al eliminar:", error);
          alert("No se pudo eliminar el cliente. Revisa la consola.");
        }
      }
    },

    resetForm() {
      this.cliente = { id: null, cedula: "", name: "", email: "", phone: "" };
    },
    goBack() {
      console.log("Botón Actualizar presionado");
    },
    goToList() {
      console.log("Botón Consultar presionado");
    }
  }
};
</script>